<?php
require_once __DIR__ . '/checkIfLoggedIn.php';
require_once __DIR__ . '/../../common/operations.php';
$billId=number_id($_GET['bill_id'] ?? ''); $table=number_id($_GET['table_id'] ?? '');
$bill=one('SELECT * FROM Bills WHERE bill_id=? AND table_id=?',[$billId,$table]);
if(!$bill) problem('Bill not found for this table.',404);
$search=text_input($_GET['search'] ?? $_POST['search'] ?? '', 'search',255,false);$like='%'.$search.'%';
$menu=db('SELECT * FROM Menu WHERE item_id LIKE ? OR item_name LIKE ? OR item_category LIKE ? OR item_type LIKE ? ORDER BY item_id',[$like,$like,$like,$like])->fetch_all(MYSQLI_ASSOC);
$lines=db('SELECT * FROM Bill_Items WHERE bill_id=? ORDER BY bill_item_id',[$billId])->fetch_all(MYSQLI_ASSOC);
$totals=bill_totals($billId);
include __DIR__ . '/../inc/dashHeader.php';
?><div class="page-header"><?php ui_heading('Table '.$table.' · Bill '.$billId,'Add items to the order and review the cart before payment.','Point of Sale'); ?><a class="btn btn-secondary" href="posTable.php">Back to tables</a></div><div class="pos-grid"><section class="surface"><h2>Food &amp; drinks</h2><form method="get" class="toolbar"><input type="hidden" name="bill_id" value="<?= h($billId) ?>"><input type="hidden" name="table_id" value="<?= h($table) ?>"><?php ui_field('search','Search menu',['value'=>$search,'required'=>false,'placeholder'=>'Search menu']); ?><div class="toolbar-actions"><button class="btn btn-primary">Search</button></div></form>
<?php if(!$menu) ui_empty('No menu items found.','Try another search.'); else { ui_table_start(['Item','Price (RM)','Add'],'Menu items'); foreach($menu as $item): ?><tr><td><strong><?= h($item['item_name']) ?></strong><br><span class="field-help"><?= h($item['item_id']) ?> · <?= h($item['item_category']) ?></span></td><td><?= h($item['item_price']) ?></td><td><?php if($bill['payment_time']===null): ?><form method="post" action="addItem.php" class="quantity-control"><?= csrf_field() ?><input type="hidden" name="bill_id" value="<?= h($billId) ?>"><input type="hidden" name="table_id" value="<?= h($table) ?>"><input type="hidden" name="item_id" value="<?= h($item['item_id']) ?>"><?php ui_field('quantity','Quantity',['id'=>'quantity-'.$item['item_id'],'type'=>'number','min'=>1,'max'=>1000,'value'=>'1']); ?><button class="btn btn-primary btn-small">Add to cart</button></form><?php else: ?><span class="status-badge">Paid</span><?php endif; ?></td></tr><?php endforeach; ui_table_end(); } ?></section>
<section class="surface"><h2>Cart</h2><?php if(!$lines) ui_empty('No items in this bill.','Add food or drinks to start the order.'); else { ui_table_start(['Item','Price (RM)','Quantity','Total (RM)','Action'],'Bill items'); foreach($lines as $line): ?><tr><td><?= h($line['item_name_snapshot']) ?></td><td><?= h($line['unit_price']) ?></td><td><?= h($line['quantity']) ?></td><td><?= money(cents($line['unit_price'])*(int)$line['quantity']) ?></td><td><?php if($bill['payment_time']===null): ?><form method="post" action="deleteItem.php"><?= csrf_field() ?><input type="hidden" name="bill_id" value="<?= h($billId) ?>"><input type="hidden" name="table_id" value="<?= h($table) ?>"><input type="hidden" name="bill_item_id" value="<?= h($line['bill_item_id']) ?>"><button class="btn btn-danger btn-small">Delete</button></form><?php else: ?><span class="status-badge">Paid</span><?php endif; ?></td></tr><?php endforeach; ui_table_end(); } ?>
<ul class="summary-list"><li><span>Subtotal</span><span>RM <?= money($totals['subtotal']) ?></span></li><li><span>Tax (10%)</span><span>RM <?= money($totals['tax']) ?></span></li><li><span>Grand total: RM <?= money($totals['total']) ?></span></li></ul><div class="form-actions"><?php if($bill['payment_time']!==null): ?><p class="info-note">Bill has already been paid.</p><a class="btn btn-primary" href="receipt.php?bill_id=<?= h($billId) ?>">Print receipt</a><?php elseif($totals['total']>0): ?><a class="btn btn-primary" href="idValidity.php?bill_id=<?= h($billId) ?>">Pay bill</a><?php else: ?><p class="field-help">Add an item before continuing to payment.</p><?php endif; ?></div></section></div><?php include __DIR__ . '/../inc/dashFooter.php'; ?>
